U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# Candidate: volatility-state conditioned medium momentum. Momentum is 20d return, attenuated in high VIX,
# and reversed only during extreme VIX shocks; all inputs lagged at t, target t+10.
px={}
for s in U:
 d=get_index_daily_data(s,days=4000)
 if d is not None and len(d): px[s]=d.set_index('date')['close'].rename(s)
v=get_index_daily_data('VIX',days=4000)
if v is None: raise RuntimeError('no VIX')
v=v.set_index('date')['close'].rename('VIX')
P=pd.concat(px.values(),axis=1).sort_index(); P=P.ffill()
R=P.pct_change(); fwd=P.shift(-10)/P-1
# candidate only: momentum weighted by inverse VIX state, with shock reversal
vix=v.reindex(P.index).ffill(); vz=(vix-vix.rolling(60).mean())/vix.rolling(60).std()
# sign remains momentum in normal regime; extreme shock uses contrarian sign, smoothly
state=np.tanh(-vz/2.0) # high VIX -> negative, low -> positive
F=R.rolling(20).sum().mul(state,axis=0)
ics=[]; Ns=[]
for dt in F.index:
 x=F.loc[dt]; y=fwd.loc[dt]; z=pd.concat([x,y],axis=1).dropna()
 if len(z)>=8:
  c=z.iloc[:,0].corr(z.iloc[:,1],method='spearman')
