for lo,hi in [('2020','2022'),('2023','2025'),('2026','2027'),('2027','2028')]:
 q=a[[str(d).startswith(tuple()) for d in []]] if False else None
 # recompute by date labels
 sub=[]
 for dt in F.index:
  if str(dt)[:4] >= lo and str(dt)[:4] <= hi:
   z=pd.concat([F.loc[dt],fwd.loc[dt]],axis=1).dropna()
   if len(z)>=8: sub.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
 sub=np.array([x for x in sub if np.isfinite(x)])
 print(lo,hi,len(sub),sub.mean() if len(sub) else np.nan,(sub.mean()/sub.std(ddof=1)) if len(sub)>1 else np.nan)
for h in [1,5,10,20]:
 Y=P.shift(-h)/P-1; aa=[]
 for dt in F.index:
  z=pd.concat([F.loc[dt],Y.loc[dt]],axis=1).dropna()
  if len(z)>=8: aa.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
